import { writeFileSync } from "node:fs";
import { execFileSync } from "node:child_process";
const [root, commit] = process.argv.slice(2);
if (!root || !/^[0-9a-f]{40}$/.test(commit ?? "")) { console.error("usage: port-luxafor-devices.mjs <openrgb-checkout> <40-hex commit>"); process.exit(2); }
const out = `// SPDX-License-Identifier: GPL-2.0-or-later
// GENERATED by scripts/openrgb/port-luxafor-devices.mjs from OpenRGB commit ${commit}.
pub const UPSTREAM_COMMIT: &str = "${commit}";
pub const VID: u16 = 0x04D8;
pub const PID: u16 = 0xF372;
`;
writeFileSync(new URL("../../modules/luxafor/src/devices_table.rs", import.meta.url), out);
execFileSync("cargo", ["fmt", "--all"], { cwd: process.cwd(), stdio: "inherit" });
console.log("1 device, 1 detector");
